/* java.lang.Math boundary contracts through the public C-to-Java call API.
 *
 * Fixed tables were generated by OpenJDK 27.0.1.0.3 using Math.abs/min/max/round
 * on explicit IEEE-754 input bits. Generator, version, commands and output:
 * .local-tools/debug-runs/math-edges-20261110-tests/ (local audit artifacts).
 * No C rounding formula computes expected values. NaN results are checked by
 * category only: Java does not promise a particular NaN sign or payload.
 * All other floating results are checked bit-for-bit, including signed zero.
 * Binary tables run in both argument orders. Wide arguments occupy slots 0,2;
 * unused slots contain sentinels to expose an accidental slot-1 read.
 */
#include "nj2me/nj.h"
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define COUNT(a) (sizeof(a) / sizeof((a)[0]))
static unsigned checks, failures, calls;
static const char *method, *descriptor;
static size_t case_index;
static unsigned reversed;

static void fixture(int ok, const char *message)
{
    if (!ok) {
        fprintf(stderr, "Math fixture failure: %s\n", message);
        exit(2);
    }
}

static void record(int ok, uint64_t got, uint64_t want)
{
    ++checks;
    if (!ok) {
        if (failures < 40) {
            fprintf(stderr, "FAIL Math.%s%s case %zu reverse=%u: "
                    "got 0x%016" PRIx64 ", want 0x%016" PRIx64 "\n",
                    method, descriptor, case_index, reversed, got, want);
        }
        ++failures;
    }
}

static void arguments(nj_value args[4])
{
    memset(args, 0, 4 * sizeof(*args));
    args[1].j = INT64_C(1234605616436508552);
    args[3].j = INT64_C(2464388554683811993);
}

static int call(nj_vm *vm, const char *name, const char *desc,
                nj_value args[4], nj_value *out)
{
    nj_status status;
    method = name;
    descriptor = desc;
    memset(out, 0xa5, sizeof(*out));
    ++calls;
    status = nj_call_static(vm, "java/lang/Math", name, desc, args, out);
    if (status != NJ_OK || nj_has_exception(vm)) {
        if (failures < 40) {
            const char *exception = nj_exception_describe(vm);
            fprintf(stderr, "FAIL Math.%s%s case %zu reverse=%u: "
                    "call status %d, exception %s\n", name, desc,
                    case_index, reversed, (int)status,
                    exception ? exception : "(none)");
        }
        ++checks;
        ++failures;
        nj_clear_exception(vm);
        return 0;
    }
    return 1;
}

static float float_input(uint32_t bits)
{
    float x;
    memcpy(&x, &bits, sizeof(x));
    return x;
}

static double double_input(uint64_t bits)
{
    double x;
    memcpy(&x, &bits, sizeof(x));
    return x;
}

static int nan_f(uint32_t bits)
{
    return (bits & UINT32_C(0x7fffffff)) > UINT32_C(0x7f800000);
}

static int nan_d(uint64_t bits)
{
    return (bits & UINT64_C(0x7fffffffffffffff)) > UINT64_C(0x7ff0000000000000);
}

static void expect_f(float value, uint32_t want)
{
    uint32_t got;
    memcpy(&got, &value, sizeof(got));
    record(nan_f(want) ? nan_f(got) : got == want, got, want);
}

static void expect_d(double value, uint64_t want)
{
    uint64_t got;
    memcpy(&got, &value, sizeof(got));
    record(nan_d(want) ? nan_d(got) : got == want, got, want);
}

