static void abs_cases(nj_vm *vm)
{
    nj_value args[4], out;
    reversed = 0;
    for (case_index = 0; case_index < COUNT(abs_i_cases); ++case_index) {
        arguments(args);
        args[0].i = abs_i_cases[case_index].x;
        if (call(vm, "abs", "(I)I", args, &out))
            record(out.i == abs_i_cases[case_index].want,
                   (uint32_t)out.i, (uint32_t)abs_i_cases[case_index].want);
    }
    for (case_index = 0; case_index < COUNT(abs_j_cases); ++case_index) {
        arguments(args);
        args[0].j = abs_j_cases[case_index].x;
        if (call(vm, "abs", "(J)J", args, &out))
            record(out.j == abs_j_cases[case_index].want,
                   (uint64_t)out.j, (uint64_t)abs_j_cases[case_index].want);
    }
    for (case_index = 0; case_index < COUNT(abs_f_cases); ++case_index) {
        arguments(args);
        args[0].f = float_input(abs_f_cases[case_index].x);
        if (call(vm, "abs", "(F)F", args, &out))
            expect_f(out.f, abs_f_cases[case_index].want);
    }
    for (case_index = 0; case_index < COUNT(abs_d_cases); ++case_index) {
        arguments(args);
        args[0].d = double_input(abs_d_cases[case_index].x);
        if (call(vm, "abs", "(D)D", args, &out))
            expect_d(out.d, abs_d_cases[case_index].want);
    }
}

static void min_max_cases(nj_vm *vm)
{
    nj_value args[4], out;
    for (reversed = 0; reversed < 2; ++reversed) {
        for (case_index = 0; case_index < COUNT(pair_i_cases); ++case_index) {
            const struct pair_i_case *p = &pair_i_cases[case_index];
            arguments(args);
            args[0].i = reversed ? p->b : p->a;
            args[1].i = reversed ? p->a : p->b;
            if (call(vm, "min", "(II)I", args, &out))
                record(out.i == p->min, (uint32_t)out.i, (uint32_t)p->min);
            if (call(vm, "max", "(II)I", args, &out))
                record(out.i == p->max, (uint32_t)out.i, (uint32_t)p->max);
        }
        for (case_index = 0; case_index < COUNT(pair_j_cases); ++case_index) {
            const struct pair_j_case *p = &pair_j_cases[case_index];
            arguments(args);
            args[0].j = reversed ? p->b : p->a;
            args[2].j = reversed ? p->a : p->b;
            if (call(vm, "min", "(JJ)J", args, &out))
                record(out.j == p->min, (uint64_t)out.j, (uint64_t)p->min);
            if (call(vm, "max", "(JJ)J", args, &out))
                record(out.j == p->max, (uint64_t)out.j, (uint64_t)p->max);
        }
        for (case_index = 0; case_index < COUNT(pair_f_cases); ++case_index) {
            const struct pair_f_case *p = &pair_f_cases[case_index];
            arguments(args);
            args[0].f = float_input(reversed ? p->b : p->a);
            args[1].f = float_input(reversed ? p->a : p->b);
            if (call(vm, "min", "(FF)F", args, &out)) expect_f(out.f, p->min);
            if (call(vm, "max", "(FF)F", args, &out)) expect_f(out.f, p->max);
        }
        for (case_index = 0; case_index < COUNT(pair_d_cases); ++case_index) {
            const struct pair_d_case *p = &pair_d_cases[case_index];
            arguments(args);
            args[0].d = double_input(reversed ? p->b : p->a);
            args[2].d = double_input(reversed ? p->a : p->b);
            if (call(vm, "min", "(DD)D", args, &out)) expect_d(out.d, p->min);
            if (call(vm, "max", "(DD)D", args, &out)) expect_d(out.d, p->max);
        }
    }
}

static void round_cases(nj_vm *vm)
{
    nj_value args[4], out;
    reversed = 0;
    /* Inputs include +/-0, subnormals, 0.5 and -0.5 plus immediate neighbors,
     * +/-1.5 neighbors, +/-2.5 ties, odd integers, limits, infinities and NaNs.
     * In particular round(nextDown(0.5d)) is 0 and round(2^52+1d) is 2^52+1;
     * neither permits a rounded double addition to manufacture a tie/integer.
     */
    for (case_index = 0; case_index < COUNT(round_f_cases); ++case_index) {
        arguments(args);
        args[0].f = float_input(round_f_cases[case_index].x);
        if (call(vm, "round", "(F)I", args, &out))
            record(out.i == round_f_cases[case_index].want,
                   (uint32_t)out.i, (uint32_t)round_f_cases[case_index].want);
    }
    for (case_index = 0; case_index < COUNT(round_d_cases); ++case_index) {
        arguments(args);
        args[0].d = double_input(round_d_cases[case_index].x);
        if (call(vm, "round", "(D)J", args, &out))
            record(out.j == round_d_cases[case_index].want,
                   (uint64_t)out.j, (uint64_t)round_d_cases[case_index].want);
    }
}

int main(void)
{
    nj_port port;
    nj_vm *vm;
    fixture(sizeof(float) == sizeof(uint32_t) && sizeof(double) == sizeof(uint64_t),
            "IEEE-754 float/double storage sizes");
    memset(&port, 0, sizeof(port));
    fixture(nj_port_headless(&port) == NJ_OK, "headless port");
    vm = nj_vm_create(&port, 2u * 1024u * 1024u);
    fixture(vm != NULL, "VM creation");
    abs_cases(vm);
    min_max_cases(vm);
    round_cases(vm);
    method = "final VM";
    descriptor = "";
    case_index = 0;
    reversed = 0;
    record(!nj_has_exception(vm), (uint64_t)nj_has_exception(vm), 0);
    nj_vm_destroy(vm);
    nj_port_shutdown(&port);
    printf("Math edges: %u calls, %u checks, %u passed, %u failed\n",
           calls, checks, checks - failures, failures);
    return failures ? 1 : 0;
}
